const slots=['09:00 AM','10:00 AM','11:30 AM','01:00 PM','02:00 PM','03:30 PM','04:30 PM','05:30 PM'];
let slotRequest=0;
async function populateSlots(){const sel=$('#time-select'),date=dateInput.value,service=$('#service-select').value,requestId=++slotRequest;sel.innerHTML='';if(!date){sel.innerHTML='<option value="">Select a date first</option>';$('#slot-message').textContent='Available appointment times will appear after you choose a day.';return;}$('#slot-message').classList.remove('error');$('#slot-message').textContent='Checking available appointment times…';sel.innerHTML='<option value="">Loading availability…</option>';try{const result=await window.wrenchApi.request(`/api/availability?date=${encodeURIComponent(date)}`);if(requestId!==slotRequest)return;const available=result.slots;if(!available.length){sel.innerHTML='<option value="">No times available</option>';$('#slot-message').textContent='No appointment times are available. Choose a different date or call us.';return;}sel.innerHTML='<option value="">Choose an available time</option>'+available.map(t=>`<option>${escapeHTML(t)}</option>`).join('');$('#slot-message').textContent=`${available.length} available appointment times${service?' for '+service.toLowerCase():''}. Pick your preferred slot.`;}catch(error){if(requestId!==slotRequest)return;sel.innerHTML='<option value="">Availability unavailable</option>';$('#slot-message').textContent=`${error.message} Please try again or call 1800 555 0123.`;$('#slot-message').classList.add('error');}}
dateInput.addEventListener('change',populateSlots);$('#service-select').addEventListener('change',populateSlots);
function scrollToBooking(service){if(service){$('#service-select').value=service;populateSlots()}$('#booking').scrollIntoView({behavior:'smooth'});setTimeout(()=>$('#booking-form [name="name"]').focus({preventScroll:true}),550)}
$('#hero-book').addEventListener('click',()=>scrollToBooking());$('#services-book').addEventListener('click',()=>scrollToBooking());$('#why-book').addEventListener('click',()=>scrollToBooking());$$('.service-footer button').forEach(b=>b.addEventListener('click',()=>scrollToBooking(b.dataset.service)));
const confirmation=$('#confirmation-modal');
$('#booking-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type="submit"]'),booking=Object.fromEntries(new FormData(form).entries());submit.disabled=true;try{const saved=await window.wrenchApi.send('/api/bookings','POST',booking);$('#confirm-name').textContent=saved.name.trim().split(/\s+/)[0];const fields=[['Service',saved.service],['Vehicle',`${saved.car} · ${saved.registration}`],['Appointment',new Date(saved.date+'T00:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · '+saved.time],['Arrangements',saved.handover],['Reference',saved.id]];$('#confirm-details').innerHTML=fields.map(([k,v])=>`<div class="confirm-row"><span>${k}</span><strong>${escapeHTML(v)}</strong></div>`).join('');openModal(confirmation);form.reset();$('#time-select').innerHTML='<option value="">Select a date first</option>';populateSlots();}catch(error){toast(error.message);if(error.status===409)populateSlots();}finally{submit.disabled=false;}});
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function openModal(m){m.classList.add('is-open');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function closeModal(m){m.classList.remove('is-open');m.setAttribute('aria-hidden','true');if(!$('.modal.is-open'))document.body.style.overflow=''}$$('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.closest('.modal'))));document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal.is-open').forEach(closeModal)});
const loginModal=$('#admin-modal'),loginForm=$('#admin-login-form'),forgotForm=$('#admin-forgot-form'),recoveryError=$('#recovery-error');$$('.admin-open').forEach(b=>b.addEventListener('click',()=>openModal(loginModal)));$('#show-forgot-password').addEventListener('click',()=>{forgotForm.elements.email.value=loginForm.elements.email.value;loginForm.hidden=true;forgotForm.hidden=false;recoveryError.classList.remove('show','success');});$('#back-to-admin-login').addEventListener('click',()=>{forgotForm.hidden=true;loginForm.hidden=false;recoveryError.classList.remove('show','success');});loginForm.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type="submit"]'),fields=Object.fromEntries(new FormData(form).entries());button.disabled=true;try{await window.wrenchApi.send('/api/admin/login','POST',fields);$('#login-error').classList.remove('show');closeModal(loginModal);await openAdmin();}catch(error){$('#login-error').textContent=error.message;$('#login-error').classList.add('show');}finally{button.disabled=false;}});forgotForm.addEventListener('submit',async e=>{e.preventDefault();const button=forgotForm.querySelector('[type="submit"]'),email=forgotForm.elements.email.value.trim();button.disabled=true;recoveryError.classList.remove('show','success');try{const result=await window.wrenchApi.send('/api/admin/forgot-password','POST',{email});recoveryError.textContent=result.message;recoveryError.classList.add('show','success');}catch(error){recoveryError.textContent=error.message;recoveryError.classList.add('show');}finally{button.disabled=false;}});
const customerModal=$('#customer-modal');$$('.customer-open').forEach(b=>b.addEventListener('click',()=>openModal(customerModal)));const savedCustomer=getData('wrench_customer',null);if(savedCustomer){$('#customer-login-form [name="name"]').value=savedCustomer.name;$('#customer-login-form [name="phone"]').value=savedCustomer.phone;$$('.customer-open').forEach(b=>b.textContent='Hi, '+savedCustomer.name.split(/\s+/)[0]);}$('#customer-login-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim(),phone=String(f.get('phone')).trim();if(name.length<2||phone.replace(/\D/g,'').length<8){$('#customer-login-error').classList.add('show');return;}const customer={name,phone};localStorage.setItem('wrench_customer',JSON.stringify(customer));$('#customer-login-error').classList.remove('show');$('#booking-form [name="name"]').value=name;$('#booking-form [name="phone"]').value=phone;$$('.customer-open').forEach(b=>b.textContent='Hi, '+name.split(/\s+/)[0]);closeModal(customerModal);scrollToBooking();toast('Your details are ready for your booking.');});
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
const admin=$('#admin-app'),content=$('#admin-content');
let roadsideRequests=[],partOrders=[],mechanicsData=[],attendanceData=[];
$('#admin-date').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
async function refreshAdminData(){const data=await window.wrenchApi.request('/api/admin/bootstrap');bookings=data.bookings;roadsideRequests=data.roadsideRequests;partOrders=data.partOrders;mechanicsData=data.mechanics;attendanceData=data.attendance;stock=data.inventory;bills=data.invoices;transactions=data.transactions;offersData=data.offers;$('#appointment-count').textContent=bookings.length;$('#booking-top-count').textContent=bookings.length;$('#roadside-count').textContent=roadsideRequests.filter(request=>!['Completed','Cancelled'].includes(request.status)).length;$('#orders-count').textContent=partOrders.filter(order=>!['Fulfilled','Cancelled'].includes(order.status)).length;}
async function openAdmin(view='overview'){admin.classList.add('is-open');admin.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';try{await refreshAdminData();renderAdmin(view);}catch(error){closeAdmin(false);toast(error.message);}}
function closeAdmin(logout=true){admin.classList.remove('is-open');admin.setAttribute('aria-hidden','true');document.body.style.overflow='';if(logout)window.wrenchApi.request('/api/admin/logout',{method:'POST'}).catch(error=>toast(error.message));}
$('#admin-logout').addEventListener('click',()=>closeAdmin());$('#admin-bookings-button').addEventListener('click',async()=>{try{await refreshAdminData();renderAdmin('appointments');}catch(error){toast(error.message);}});$$('.side-link').forEach(b=>b.addEventListener('click',async()=>{try{await refreshAdminData();renderAdmin(b.dataset.view);}catch(error){toast(error.message);}}));$('#appointment-count').textContent=bookings.length;$('#booking-top-count').textContent=bookings.length;
function setActive(view){$$('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#appointment-count').textContent=bookings.length;$('#booking-top-count').textContent=bookings.length;$('#roadside-count').textContent=roadsideRequests.filter(request=>!['Completed','Cancelled'].includes(request.status)).length;}
function pageHeading(title,sub,button=''){return `<div class="admin-page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function metric(label,value,foot,icon){return `<article class="metric-card"><div class="metric-head"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`}
function overview(){const todayBookings=bookings.filter(b=>b.date===todayISO());const revenue=transactions.filter(t=>t.type==='Sale').reduce((s,t)=>s+Number(t.amount),0);const low=stock.filter(x=>x.qty<=x.min).length;const pending=bills.filter(b=>b.status!=='Paid').reduce((s,b)=>s+Number(b.amount),0);const max=46000;const vals=[22000,31000,28000,42000,35000,39000,33000,46000,42000,51000,44000,Math.max(30000,revenue)];const pts=vals.map((v,i)=>`${30+i*57},${152-(v/max)*123}`).join(' ');return `${pageHeading('Good morning, Arjun 👋','Here’s what’s happening at the workshop today.',`<button class="button button-primary" data-nav="appointments">+ &nbsp;Manage bookings</button>`)}<div class="metric-grid">${metric('TOTAL REVENUE',money(revenue),'<span class="up">↑ 12.8%</span> vs last month','↗')}${metric('APPOINTMENTS TODAY',todayBookings.length,`${bookings.length} active bookings total`,'▣')}${metric('PARTS IN STOCK',stock.reduce((s,x)=>s+x.qty,0),`<span class="${low?'':'up'}">${low} low stock</span> · ${stock.length} product types`,'◈')}${metric('PENDING BILLS',money(pending),`${bills.filter(b=>b.status!=='Paid').length} invoices to follow up`,'₹')}</div><div class="admin-panels"><section class="admin-panel"><div class="panel-head"><div><h3>Revenue overview</h3><p>Monthly sales performance</p></div><div class="chart-legend"><span><i class="legend-dot"></i> Revenue</span><span><i class="legend-dot muted"></i> Last year</span></div></div><svg class="revenue-chart" viewBox="0 0 690 180" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#b7ef65" stop-opacity=".35"/><stop offset="1" stop-color="#b7ef65" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M25 35H675M25 75H675M25 115H675M25 155H675"/><text class="chart-label" x="0" y="38">₹60k</text><text class="chart-label" x="0" y="78">₹40k</text><text class="chart-label" x="0" y="118">₹20k</text><text class="chart-label" x="10" y="158">₹0</text><polyline class="chart-line-secondary" points="30,120 87,105 144,112 201,90 258,101 315,82 372,93 429,79 486,98 543,69 600,77 657,54"/><polygon class="chart-area" points="30,152 ${pts} 657,152"/><polyline class="chart-line" points="${pts}"/><circle class="chart-point" cx="657" cy="${152-(Math.max(30000,revenue)/max)*123}" r="4"/></svg><div class="bar-labels"><span>OCT</span><span>NOV</span><span>DEC</span><span>JAN</span><span>FEB</span><span>MAR</span><span>APR</span><span>MAY</span><span>JUN</span><span>JUL</span><span>AUG</span><span>SEP</span></div></section><section class="admin-panel"><div class="panel-head"><div><h3>Today’s appointments</h3><p>${todayBookings.length} scheduled visits</p></div><button data-nav="appointments">View all ↗</button></div>${todayBookings.length?`<div class="activity-list">${todayBookings.slice(0,4).map(b=>`<div class="activity-row"><div class="activity-avatar">${escapeHTML(b.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><div class="activity-info"><strong>${escapeHTML(b.name)}</strong><small>${escapeHTML(b.car)} · ${escapeHTML(b.time)}</small></div><span class="status-pill ${b.status.includes('Awaiting')?'pending':''}">${escapeHTML(b.status)}</span></div>`).join('')}</div>`:'<div class="empty-state">No appointments booked for today.</div>'}</section><section class="admin-panel"><div class="panel-head"><div><h3>Recent activity</h3><p>Sales and purchases</p></div><button data-nav="finance">See ledger ↗</button></div><div class="activity-list">${transactions.slice(0,4).map(t=>`<div class="activity-row"><div class="activity-avatar ${t.type==='Purchase'?'orange':''}">${t.type==='Sale'?'↗':'↓'}</div><div class="activity-info"><strong>${escapeHTML(t.party)}</strong><small>${escapeHTML(t.detail)}</small></div><span class="activity-amount">${t.type==='Purchase'?'−':'+'}${money(t.amount)}</span></div>`).join('')}</div></section><section class="admin-panel"><div class="panel-head"><div><h3>Stock to watch</h3><p>Items at or below minimum level</p></div><button data-nav="inventory">Manage stock ↗</button></div><div class="stock-list">${stock.filter(x=>x.qty<=x.min).length?stock.filter(x=>x.qty<=x.min).map(x=>`<div class="stock-row"><div class="activity-info"><strong>${escapeHTML(x.name)}</strong><small>${escapeHTML(x.sku)} · minimum ${x.min}</small></div><span class="status-pill low">${x.qty} left</span></div>`).join(''):'<div class="empty-state">All parts are stocked above the minimum level.</div>'}</div></section></div>`}
function appointments(){return `${pageHeading('Appointments','Review, confirm and manage customer bookings.',`<button class="button button-outline" data-export="appointments">↓ &nbsp;Export bookings</button>`)}<div class="section-toolbar"><input id="appointment-search" placeholder="Search name, car or reference…"/><select id="appointment-filter"><option value="all">All statuses</option><option>Awaiting confirmation</option><option>Confirmed</option><option>In progress</option><option>Completed</option><option>Cancelled</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REFERENCE</th><th>CUSTOMER &amp; VEHICLE</th><th>SERVICE</th><th>DATE &amp; TIME</th><th>ARRANGEMENT</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody id="appointment-rows"></tbody></table></div>`}
function renderAppointmentRows(){const q=($('#appointment-search')?.value||'').toLowerCase(),filter=$('#appointment-filter')?.value||'all';const filtered=bookings.filter(b=>(filter==='all'||b.status===filter)&&`${b.name} ${b.car} ${b.id} ${b.registration}`.toLowerCase().includes(q));const body=$('#appointment-rows');if(!body)return;body.innerHTML=filtered.length?filtered.map(b=>`<tr><td><strong>${escapeHTML(b.id)}</strong></td><td><strong>${escapeHTML(b.name)}</strong><br>${escapeHTML(b.car)} · ${escapeHTML(b.registration)}</td><td>${escapeHTML(b.service)}</td><td>${new Date(b.date+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}<br>${escapeHTML(b.time)}</td><td>${escapeHTML(b.handover)}</td><td><span class="status-pill ${b.status==='Awaiting confirmation'?'pending':b.status==='Cancelled'?'low':''}">${escapeHTML(b.status)}</span></td><td><div class="table-actions"><button data-status="${b.id}">${b.status==='Awaiting confirmation'?'Confirm':b.status==='Confirmed'?'Start':'Complete'}</button><button data-cancel="${b.id}">×</button></div></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">No bookings match your search.</td></tr>';}
function roadside(){const open=roadsideRequests.filter(request=>!['Completed','Cancelled'].includes(request.status)).length;return `${pageHeading('Roadside assistance','Review incoming breakdown reports and keep customers updated.',`<span class="status-pill ${open?'pending':''}">${open} open requests</span>`)}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REQUEST</th><th>CUSTOMER</th><th>VEHICLE &amp; ISSUE</th><th>LOCATION &amp; CONDITION</th><th>MECHANIC</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${roadsideRequests.length?roadsideRequests.map(request=>{const next=request.status==='New'?'Contacting customer':request.status==='Contacting customer'?'Dispatched':'Completed';return `<tr><td><strong>${escapeHTML(request.id)}</strong><br><small>${escapeHTML(new Date(request.createdAt).toLocaleString('en-IN'))}</small></td><td><strong>${escapeHTML(request.name)}</strong><br><a href="tel:${escapeHTML(request.phone)}">${escapeHTML(request.phone)}</a></td><td>${escapeHTML(request.vehicle)}<br>${escapeHTML(request.registration)}<br><span class="status-pill pending">${escapeHTML(request.issue)}</span></td><td>${escapeHTML(request.location)}<br><small>${escapeHTML(request.details)}</small></td><td>${escapeHTML(request.mechanic||'Match requested')}</td><td><span class="status-pill ${request.status==='New'?'pending':request.status==='Cancelled'?'low':''}">${escapeHTML(request.status)}</span></td><td>${['Completed','Cancelled'].includes(request.status)?'—':`<button class="small-action" data-roadside-status="${escapeHTML(request.id)}" data-next="${next}">${next}</button><button class="small-action" data-roadside-status="${escapeHTML(request.id)}" data-next="Cancelled">Cancel</button>`}</td></tr>`}).join(''):'<tr><td colspan="7" class="empty-state">No roadside assistance requests yet.</td></tr>'}</tbody></table></div>`}
function partOrdersView(){return `${pageHeading('Parts requests','Review customer baskets and confirm availability before arranging collection.')}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REQUEST</th><th>CUSTOMER</th><th>PARTS</th><th>TOTAL</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${partOrders.length?partOrders.map(order=>{const lines=JSON.parse(order.lines);const next=order.status==='Requested'?'Confirmed':'Fulfilled';return `<tr><td><strong>${escapeHTML(order.id)}</strong><br><small>${escapeHTML(new Date(order.createdAt).toLocaleString('en-IN'))}</small></td><td><strong>${escapeHTML(order.name)}</strong><br><a href="tel:${escapeHTML(order.phone)}">${escapeHTML(order.phone)}</a></td><td>${lines.map(line=>`${escapeHTML(line.name)} × ${line.quantity}`).join('<br>')}</td><td><strong>${money(order.total)}</strong></td><td><span class="status-pill ${order.status==='Requested'?'pending':''}">${escapeHTML(order.status)}</span></td><td>${['Fulfilled','Cancelled'].includes(order.status)?'—':`<button class="small-action" data-part-order="${escapeHTML(order.id)}" data-next="${next}">${next}</button><button class="small-action" data-part-order="${escapeHTML(order.id)}" data-next="Cancelled">Cancel</button>`}</td></tr>`}).join(''):'<tr><td colspan="6" class="empty-state">No customer parts requests yet.</td></tr>'}</tbody></table></div>`}
function mechanicsAdmin(){return `${pageHeading('Mechanics','Manage the team customers can select and the specialists available for dispatch.',`<button class="button button-primary" data-mechanic-add>+ &nbsp;Add mechanic</button>`)}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>MECHANIC</th><th>SPECIALTY</th><th>SKILLS</th><th>EXPERIENCE</th><th>AREA</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${mechanicsData.map(mechanic=>`<tr><td><strong>${escapeHTML(mechanic.name)}</strong><br>${escapeHTML(mechanic.initials)} · ${escapeHTML(String(mechanic.rating))} ★</td><td>${escapeHTML(mechanic.specialty)}<br><small>${escapeHTML(mechanic.description)}</small></td><td>${escapeHTML(mechanic.skills.replaceAll(', ', ' · ').replaceAll(',', ' · '))}</td><td>${escapeHTML(String(mechanic.experience))} years</td><td>${escapeHTML(mechanic.location)}</td><td><span class="status-pill ${mechanic.status==='Unavailable'?'low':''}">${escapeHTML(mechanic.status)}</span></td><td><button class="small-action" data-mechanic-status="${mechanic.id}" data-next="${mechanic.status==='Available'?'Unavailable':'Available'}">Set ${mechanic.status==='Available'?'unavailable':'available'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">No mechanics have been added.</td></tr>'}</tbody></table></div>`}
function mechanicPerformance(){const month=todayISO().slice(0,7),monthAttendance=attendanceData.filter(item=>item.date.startsWith(month)),completedJobs=bookings.filter(item=>item.status==='Completed'&&item.date.startsWith(month)),hoursFor=items=>items.reduce((sum,item)=>sum+Math.max(0,((item.checkOut?new Date(item.checkOut).getTime():item.date===todayISO()?Date.now():new Date(item.checkIn).getTime())-new Date(item.checkIn).getTime())/3600000),0),payroll=mechanicsData.reduce((sum,item)=>sum+Number(item.monthlySalary||0),0),totalHours=hoursFor(monthAttendance),today=attendanceData.find(item=>item.date===todayISO());const cards=mechanicsData.map(mechanic=>{const records=monthAttendance.filter(item=>item.mechanicId===mechanic.id),hours=hoursFor(records),jobs=completedJobs.filter(item=>item.mechanicId===mechanic.id).length,shift=records.find(item=>item.date===todayISO()),clock=shift?.checkOut?'Checked out':shift?'On shift':'Not checked in';return `<article class="performance-card"><div class="performance-card-head"><div class="performance-avatar">${escapeHTML(mechanic.initials)}</div><div><h3>${escapeHTML(mechanic.name)}</h3><p>${escapeHTML(mechanic.specialty)}</p></div><span class="status-pill ${shift&&!shift.checkOut?'performance-on-shift':''}">${clock}</span></div><div class="performance-stats"><div><span>COMPLETED JOBS</span><strong>${jobs}</strong></div><div><span>HOURS THIS MONTH</span><strong>${hours.toFixed(1)}<small> hrs</small></strong></div><div><span>SHIFTS THIS MONTH</span><strong>${records.length}</strong></div></div><div class="performance-salary"><span>MONTHLY SALARY</span><strong>${mechanic.monthlySalary?money(mechanic.monthlySalary):'Not set'}</strong><button class="small-action" data-salary="${mechanic.id}">${mechanic.monthlySalary?'Edit':'Set salary'}</button></div><div class="performance-actions">${shift&&!shift.checkOut?`<button class="button button-primary" data-attendance="${mechanic.id}" data-action="check-out">Check out</button><small>Checked in ${new Date(shift.checkIn).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</small>`:`<button class="button button-outline" data-attendance="${mechanic.id}" data-action="check-in" ${shift?.checkOut?'disabled title="A shift is already recorded for today"':''}>Check in</button>${shift?.checkOut?`<small>Today’s shift: ${Math.max(0,(new Date(shift.checkOut)-new Date(shift.checkIn))/3600000).toFixed(1)} hours</small>`:'<small>Start today’s work-hour record</small>'}`}</div></article>`}).join('');const jobsTable=completedJobs.map(job=>`<tr><td><strong>${escapeHTML(job.id)}</strong><br>${escapeHTML(job.date)}</td><td><strong>${escapeHTML(job.name)}</strong><br>${escapeHTML(job.car)}</td><td>${escapeHTML(job.service)}</td><td><select class="booking-mechanic-select" data-booking-mechanic="${escapeHTML(job.id)}" aria-label="Attribute completed booking ${escapeHTML(job.id)} to mechanic"><option value="">Unassigned</option>${mechanicsData.map(mechanic=>`<option value="${mechanic.id}" ${mechanic.id===job.mechanicId?'selected':''}>${escapeHTML(mechanic.name)}</option>`).join('')}</select></td></tr>`).join('');return `${pageHeading('Team performance','Track completed workshop jobs, attendance, work hours and monthly mechanic salaries.',`<span class="performance-month">${new Date(`${month}-01T00:00:00`).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</span>`)}<div class="metric-grid">${metric('COMPLETED JOBS',completedJobs.length,'Completed and assigned bookings','✓')}${metric('HOURS TRACKED',`${totalHours.toFixed(1)} hrs`,`${monthAttendance.length} shifts recorded this month`,'◷')}${metric('MONTHLY PAYROLL',money(payroll),`${mechanicsData.filter(item=>item.monthlySalary>0).length} of ${mechanicsData.length} salaries configured`,'₹')}${metric('ON SHIFT TODAY',attendanceData.filter(item=>item.date===todayISO()&&!item.checkOut).length,'Mechanics currently checked in','♙')}</div><div class="performance-grid">${cards||'<div class="admin-panel empty-state">Add mechanics to manage team attendance and salaries.</div>'}</div><section class="admin-panel performance-jobs"><div class="panel-head"><div><h3>Completed jobs</h3><p>Assign completed appointments to include them in mechanic performance totals.</p></div><button data-nav="appointments">Manage appointments ↗</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>BOOKING / DATE</th><th>CUSTOMER / VEHICLE</th><th>SERVICE</th><th>MECHANIC</th></tr></thead><tbody>${jobsTable||'<tr><td colspan="4" class="empty-state">Completed appointments this month will appear here.</td></tr>'}</tbody></table></div></section>`}
function inventory(){const all=stock.reduce((s,x)=>s+x.qty,0),value=stock.reduce((s,x)=>s+x.qty*x.cost,0),low=stock.filter(x=>x.qty<=x.min).length;return `${pageHeading('Parts & inventory','Track genuine parts, accessories and spare parts in your workshop.',`<button class="button button-primary" data-stock-add>+ &nbsp;Add part</button>`)}<div class="inventory-summary"><div class="inventory-tile"><span>TOTAL UNITS IN STOCK</span><strong>${all}</strong></div><div class="inventory-tile"><span>STOCK VALUE AT COST</span><strong>${money(value)}</strong></div><div class="inventory-tile"><span>LOW STOCK ALERTS</span><strong>${low}</strong></div></div><div class="section-toolbar"><input id="stock-search" placeholder="Search part name, SKU or brand…"/><select id="stock-filter"><option value="all">All categories</option><option>Genuine parts</option><option>Accessories</option><option>Spare parts</option></select><button class="button button-outline" data-stock-move="in">↓ &nbsp;Stock in</button><button class="button button-outline" data-stock-move="out">↑ &nbsp;Stock out</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>SKU / PART</th><th>CATEGORY</th><th>BRAND</th><th>QTY ON HAND</th><th>MIN. LEVEL</th><th>COST / UNIT</th><th>SELL PRICE</th><th>ACTIONS</th></tr></thead><tbody id="stock-rows"></tbody></table></div>`}
function renderStockRows(){const body=$('#stock-rows');if(!body)return;const q=($('#stock-search')?.value||'').toLowerCase(),cat=$('#stock-filter')?.value||'all',items=stock.filter(x=>(cat==='all'||x.category===cat)&&`${x.name} ${x.sku} ${x.brand}`.toLowerCase().includes(q));body.innerHTML=items.length?items.map(x=>`<tr><td><strong>${escapeHTML(x.name)}</strong><br>${escapeHTML(x.sku)}</td><td>${escapeHTML(x.category)}</td><td>${escapeHTML(x.brand)}</td><td><span class="status-pill ${x.qty<=x.min?'low':''}">${x.qty}</span></td><td>${x.min}</td><td>${money(x.cost)}</td><td>${money(x.price)}</td><td><div class="table-actions"><button data-stock-move="in" data-sku="${x.sku}">+ In</button><button data-stock-move="out" data-sku="${x.sku}">− Out</button></div></td></tr>`).join(''):'<tr><td colspan="8" class="empty-state">No inventory items match your search.</td></tr>'}
function finance(){const sales=transactions.filter(t=>t.type==='Sale').reduce((s,t)=>s+Number(t.amount),0),purchases=transactions.filter(t=>t.type==='Purchase').reduce((s,t)=>s+Number(t.amount),0),owed=bills.filter(b=>b.status!=='Paid').reduce((s,b)=>s+Number(b.amount),0);return `${pageHeading('Sales & finance','Follow revenue, record purchases and keep pending bills visible.',`<button class="button button-primary" data-record-sale>+ &nbsp;Record sale</button>`)}<div class="finance-grid" style="margin-bottom:14px"><div class="finance-stat"><span>RECORDED SALES</span><strong>${money(sales)}</strong></div><div class="finance-stat"><span>RECORDED PURCHASES</span><strong>${money(purchases)}</strong></div><div class="finance-stat"><span>OUTSTANDING BILLS</span><strong>${money(owed)}</strong></div><div class="finance-stat"><span>NET CASH FLOW</span><strong>${money(sales-purchases)}</strong></div></div><section class="admin-panel" style="margin-bottom:14px"><div class="panel-head"><div><h3>Pending bills</h3><p>Mark invoices paid as customer payments arrive.</p></div><span class="status-pill pending">${bills.filter(b=>b.status!=='Paid').length} to follow up</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>DETAILS</th><th>AMOUNT DUE</th><th>DUE DATE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${bills.map(b=>`<tr><td><strong>${escapeHTML(b.id)}</strong></td><td>${escapeHTML(b.customer)}</td><td>${escapeHTML(b.desc)}</td><td><strong>${money(b.amount)}</strong></td><td>${escapeHTML(b.due)}</td><td><span class="status-pill ${b.status==='Paid'?'':b.status==='Overdue'?'low':'pending'}">${b.status}</span></td><td>${b.status==='Paid'?'<span class="status-pill">Received ✓</span>':`<button class="small-action" data-pay="${b.id}">Mark paid</button>`}</td></tr>`).join('')}</tbody></table></div></section><section class="admin-panel"><div class="panel-head"><div><h3>Sales &amp; purchases ledger</h3><p>Recent workshop transactions</p></div><button data-export="ledger">↓ &nbsp;Export</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REFERENCE</th><th>TYPE</th><th>PARTY</th><th>DESCRIPTION</th><th>DATE</th><th>AMOUNT</th></tr></thead><tbody>${transactions.map(t=>`<tr><td><strong>${t.id}</strong></td><td><span class="status-pill ${t.type==='Purchase'?'pending':''}">${t.type}</span></td><td>${escapeHTML(t.party)}</td><td>${escapeHTML(t.detail)}</td><td>${escapeHTML(t.date)}</td><td><strong>${money(t.amount)}</strong></td></tr>`).join('')}</tbody></table></div></section>`}
function offers(){return `${pageHeading('Offers & savings','Keep customer promotions current and easy to find.',`<button class="button button-primary" data-offer-add>+ &nbsp;Create offer</button>`)}<div class="offers-grid">${offersData.map(o=>`<article class="offer-card"><span class="offer-badge">${escapeHTML(o.tag)}</span><h3>${escapeHTML(o.title)}</h3><p>${escapeHTML(o.desc)}</p><small>${escapeHTML(o.when)} · CODE ${escapeHTML(o.code)}</small></article>`).join('')}</div><div class="admin-panel" style="margin-top:15px"><div class="panel-head"><div><h3>Customer savings</h3><p>Discounts and complimentary services redeemed in the last 30 days</p></div></div><div class="finance-grid"><div class="finance-stat"><span>TOTAL CUSTOMER SAVINGS</span><strong>₹28,450</strong></div><div class="finance-stat"><span>OFFERS REDEEMED</span><strong>37 visits</strong></div></div></div>`}
function renderAdmin(view='overview'){setActive(view);content.dataset.view=view;content.innerHTML=view==='overview'?overview():view==='appointments'?appointments():view==='roadside'?roadside():view==='mechanics'?mechanicsAdmin():view==='performance'?mechanicPerformance():view==='orders'?partOrdersView():view==='inventory'?inventory():view==='finance'?finance():offers();if(view==='appointments')renderAppointmentRows();if(view==='inventory')renderStockRows();content.scrollTop=0;}
content.addEventListener('click',async e=>{
  const target=e.target.closest('[data-roadside-status],[data-part-order],[data-mechanic-status],[data-mechanic-add],[data-attendance],[data-salary],[data-status],[data-cancel],[data-stock-move],[data-stock-add],[data-pay],[data-record-sale],[data-offer-add]');
  if(!target)return;
  e.stopImmediatePropagation();
  try{
    if(target.dataset.roadsideStatus){
      const request=roadsideRequests.find(item=>item.id===target.dataset.roadsideStatus);
      const mechanic=request?.mechanic||'';
      await window.wrenchApi.send(`/api/admin/roadside-requests/${encodeURIComponent(target.dataset.roadsideStatus)}`,'PATCH',{status:target.dataset.next,mechanic});
      await refreshAdminData();renderAdmin('roadside');toast(`Roadside request updated to ${target.dataset.next}.`);return;
    }
    if(target.dataset.partOrder){
      await window.wrenchApi.send(`/api/admin/part-orders/${encodeURIComponent(target.dataset.partOrder)}`,'PATCH',{status:target.dataset.next});
      await refreshAdminData();renderAdmin('orders');toast(`Parts request ${target.dataset.partOrder} updated.`);return;
    }
    if(target.dataset.mechanicStatus){
      await window.wrenchApi.send(`/api/admin/mechanics/${encodeURIComponent(target.dataset.mechanicStatus)}`,'PATCH',{status:target.dataset.next});
      await refreshAdminData();renderAdmin('mechanics');toast('Mechanic availability updated.');return;
    }
    if(target.dataset.attendance){
      await window.wrenchApi.send('/api/admin/mechanic-attendance','POST',{mechanicId:Number(target.dataset.attendance),action:target.dataset.action});
      await refreshAdminData();renderAdmin('performance');toast(target.dataset.action==='check-in'?'Mechanic checked in.':'Mechanic checked out.');return;
    }
    if(target.dataset.salary){
      const mechanic=mechanicsData.find(item=>item.id===Number(target.dataset.salary));
      if(!mechanic)return;
      const value=prompt(`Monthly salary for ${mechanic.name} (₹, whole numbers only):`,String(mechanic.monthlySalary||''));
      if(value===null)return;
      const monthlySalary=Number(value);
      if(!Number.isSafeInteger(monthlySalary)||monthlySalary<0||monthlySalary>10000000){toast('Enter a whole-number salary between ₹0 and ₹10,000,000.');return;}
      await window.wrenchApi.send(`/api/admin/mechanics/${mechanic.id}/salary`,'PATCH',{monthlySalary});
      await refreshAdminData();renderAdmin('performance');toast(`Salary saved for ${mechanic.name}.`);return;
    }
    if(target.hasAttribute('data-mechanic-add')){
      const name=prompt('Mechanic name:');if(!name)return;
      const initials=prompt('Two or three letter initials:');if(!initials)return;
      const specialty=prompt('Specialty:');if(!specialty)return;
      const description=prompt('Specialist description (10 characters minimum):');if(!description)return;
      const skills=prompt('Skills (comma-separated):');if(!skills)return;
      const location=prompt('Service area:');if(!location)return;
      const experience=Number(prompt('Years of experience:','5')),rating=Number(prompt('Rating from 0 to 5:','4.8'));
      await window.wrenchApi.send('/api/admin/mechanics','POST',{name,initials,specialty,description,skills,location,experience,rating});
      await refreshAdminData();renderAdmin('mechanics');toast(`${name} added to the mechanic directory.`);return;
    }
    if(target.dataset.status||target.dataset.cancel){
      const id=target.dataset.status||target.dataset.cancel;
      const booking=bookings.find(item=>item.id===id);
      if(!booking)return;
      const status=target.dataset.cancel?'Cancelled':booking.status==='Awaiting confirmation'?'Confirmed':booking.status==='Confirmed'?'In progress':'Completed';
      await window.wrenchApi.send(`/api/admin/bookings/${encodeURIComponent(id)}`,'PATCH',{status});
      await refreshAdminData();renderAdmin('appointments');toast(`Booking ${id} updated to ${status}.`);return;
    }
    if(target.dataset.stockMove){
      let part=target.dataset.sku?stock.find(item=>item.sku===target.dataset.sku):null;
      if(!part){const sku=prompt('Enter the part SKU to update:');if(!sku)return;part=stock.find(item=>item.sku.toLowerCase()===sku.trim().toLowerCase());if(!part){toast('Part SKU not found.');return;}}
      const quantity=Number(prompt(`How many units to stock ${target.dataset.stockMove}?`));
      if(!Number.isInteger(quantity)||quantity<1){toast('Enter a whole number greater than zero.');return;}
      const party=target.dataset.stockMove==='in'?prompt('Supplier name?',part.brand)||part.brand:'Workshop use';
      await window.wrenchApi.send(`/api/admin/inventory/${encodeURIComponent(part.sku)}`,'PATCH',{direction:target.dataset.stockMove,quantity,party});
      await refreshAdminData();renderAdmin('inventory');toast(`Stock ${target.dataset.stockMove==='in'?'received':'updated'} for ${part.name}.`);return;
    }
    if(target.hasAttribute('data-stock-add')){
      const name=prompt('Part name:');if(!name)return;const sku=prompt('SKU:');if(!sku)return;
      const qty=Number(prompt('Opening stock quantity:','0'));if(!Number.isInteger(qty)||qty<0){toast('Enter a whole number of zero or more.');return;}
      const category=prompt('Category (Genuine parts, Accessories, Spare parts):','Genuine parts')||'Genuine parts';
      const brand=prompt('Brand:','Unbranded')||'Unbranded';
      const cost=Number(prompt('Cost per unit (₹):','0')),price=Number(prompt('Selling price per unit (₹):','0'));
      await window.wrenchApi.send('/api/admin/inventory','POST',{sku,name,category,brand,qty,min:5,cost,price});
      await refreshAdminData();renderAdmin('inventory');toast(`${name} added to inventory.`);return;
    }
    if(target.dataset.pay){
      await window.wrenchApi.send(`/api/admin/invoices/${encodeURIComponent(target.dataset.pay)}`,'PATCH',{});
      await refreshAdminData();renderAdmin('finance');toast(`${target.dataset.pay} marked as paid.`);return;
    }
    if(target.hasAttribute('data-record-sale')){
      const party=prompt('Customer name:');if(!party)return;const detail=prompt('Description:');if(!detail)return;
      const amount=Number(prompt('Amount (₹):'));if(!Number.isFinite(amount)||amount<=0){toast('Enter a valid amount.');return;}
      await window.wrenchApi.send('/api/admin/transactions','POST',{type:'Sale',party,detail,amount});
      await refreshAdminData();renderAdmin('finance');toast('Sale recorded.');return;
    }
    if(target.hasAttribute('data-offer-add')){
      const title=prompt('Offer title:');if(!title)return;
      const desc=prompt('Offer description:');if(!desc)return;
      const when=prompt('Offer validity or terms:');if(!when)return;
      const code=prompt('Offer code:');if(!code)return;
      const tag=prompt('Offer badge, e.g. SAVE ₹500:','NEW OFFER')||'NEW OFFER';
      await window.wrenchApi.send('/api/admin/offers','POST',{tag,title,desc,when,code});
      await refreshAdminData();renderAdmin('offers');toast('Offer saved.');return;
    }
  }catch(error){toast(error.message);}
});
content.addEventListener('change',async e=>{const select=e.target.closest('[data-booking-mechanic]');if(!select)return;try{await window.wrenchApi.send(`/api/admin/bookings/${encodeURIComponent(select.dataset.bookingMechanic)}`,'PATCH',{mechanicId:select.value?Number(select.value):null});await refreshAdminData();renderAdmin('performance');toast('Completed job assignment updated.');}catch(error){toast(error.message);}});
content.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){renderAdmin(nav.dataset.nav);return;}const status=e.target.closest('[data-status]');if(status){const b=bookings.find(x=>x.id===status.dataset.status);if(b){b.status=b.status==='Awaiting confirmation'?'Confirmed':b.status==='Confirmed'?'In progress':'Completed';save();renderAdmin('appointments');toast(`Booking ${b.id} updated to ${b.status}.`)}return;}const cancel=e.target.closest('[data-cancel]');if(cancel){const b=bookings.find(x=>x.id===cancel.dataset.cancel);if(b){b.status='Cancelled';save();renderAdmin('appointments');toast('Booking cancelled.')}return;}const move=e.target.closest('[data-stock-move]');if(move){let item=move.dataset.sku?stock.find(x=>x.sku===move.dataset.sku):null;const direction=move.dataset.stockMove;if(!item){const sku=prompt('Enter the part SKU to update:');if(!sku)return;item=stock.find(x=>x.sku.toLowerCase()===sku.trim().toLowerCase());if(!item){toast('Part SKU not found.');return;}}const qty=Number(prompt(`How many units to stock ${direction}?`));if(!Number.isInteger(qty)||qty<1){toast('Enter a whole number greater than zero.');return;}if(direction==='out'&&qty>item.qty){toast(`Only ${item.qty} units are currently in stock.`);return;}item.qty+=direction==='in'?qty:-qty;if(direction==='in')transactions.unshift({id:'TX-'+(9022+transactions.length),type:'Purchase',party:prompt('Supplier name?')||item.brand,detail:`${item.name} · ${qty} units`,amount:item.cost*qty,date:todayISO()});else transactions.unshift({id:'TX-'+(9022+transactions.length),type:'Sale',party:'Workshop use',detail:`${item.name} · ${qty} units`,amount:item.price*qty,date:todayISO()});save();renderAdmin(content.dataset.view);toast(`Stock ${direction==='in'?'received':'updated'} for ${item.name}.`);return;}const pay=e.target.closest('[data-pay]');if(pay){const b=bills.find(x=>x.id===pay.dataset.pay);if(b){b.status='Paid';transactions.unshift({id:'TX-'+(9022+transactions.length),type:'Sale',party:b.customer,detail:`Invoice ${b.id} payment`,amount:b.amount,date:todayISO()});save();renderAdmin('finance');toast(`${b.id} marked as paid.`)}return;}if(e.target.closest('[data-stock-add]')){const name=prompt('Part name:');if(!name)return;const sku=prompt('SKU:');if(!sku)return;if(stock.some(x=>x.sku.toLowerCase()===sku.toLowerCase())){toast('That SKU already exists.');return;}const qty=Number(prompt('Opening stock quantity:','0'));if(!Number.isInteger(qty)||qty<0){toast('Enter a whole number of zero or more.');return;}const category=prompt('Category (Genuine parts, Accessories, Spare parts):','Genuine parts')||'Genuine parts';const brand=prompt('Brand:','Unbranded')||'Unbranded';const cost=Number(prompt('Cost per unit (₹):','0'))||0,price=Number(prompt('Selling price per unit (₹):','0'))||0;stock.push({sku:sku.toUpperCase(),name,category,brand,qty,min:5,cost,price});save();renderAdmin('inventory');toast(`${name} added to inventory.`);return;}if(e.target.closest('[data-record-sale]')){recordTransaction('Sale');return;}if(e.target.closest('[data-offer-add]')){const title=prompt('Offer title:');if(title)toast(`“${title}” saved as a draft offer.`);return;}if(e.target.closest('[data-export]')){exportCSV(e.target.closest('[data-export]').dataset.export);return;}});
content.addEventListener('input',e=>{if(e.target.id==='appointment-search')renderAppointmentRows();if(e.target.id==='stock-search')renderStockRows()});content.addEventListener('change',e=>{if(e.target.id==='appointment-filter')renderAppointmentRows();if(e.target.id==='stock-filter')renderStockRows()});
function recordTransaction(type){const party=prompt(type==='Sale'?'Customer name:':'Supplier name:');if(!party)return;const detail=prompt('Description:');if(!detail)return;const amount=Number(prompt('Amount (₹):'));if(!amount||amount<0){toast('Enter a valid amount.');return;}transactions.unshift({id:'TX-'+(9022+transactions.length),type,party,detail,amount,date:todayISO()});save();renderAdmin('finance');toast(`${type} recorded.`)}
function exportCSV(which){let rows;if(which==='appointments')rows=[['Reference','Name','Phone','Car','Registration','Service','Date','Time','Handover','Status'],...bookings.map(b=>[b.id,b.name,b.phone,b.car,b.registration,b.service,b.date,b.time,b.handover,b.status])];else rows=[['Reference','Type','Party','Description','Date','Amount'],...transactions.map(t=>[t.id,t.type,t.party,t.detail,t.date,t.amount])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`wrench-${which}-${todayISO()}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Your CSV export has downloaded.')}
$('.menu-toggle').addEventListener('click',()=>$('.main-nav').classList.toggle('open'));$$('.nav-link').forEach(a=>a.addEventListener('click',()=>{$$('.nav-link').forEach(n=>n.classList.remove('active'));a.classList.add('active');$('.main-nav').classList.remove('open')}));
async function loadMechanics(){const grid=$('.mechanic-grid');if(!grid)return;try{const mechanics=await window.wrenchApi.request('/api/mechanics');grid.innerHTML=mechanics.map(mechanic=>`<article class="mechanic-card"><div class="mechanic-avatar">${escapeHTML(mechanic.initials)}</div><div class="mechanic-rating">★★★★★ <strong>${escapeHTML(String(mechanic.rating))}</strong></div><h3>${escapeHTML(mechanic.name)}</h3><p class="mechanic-specialty">${escapeHTML(mechanic.specialty)}</p><p class="mechanic-bio">${escapeHTML(mechanic.description)}</p><div class="mechanic-tags">${mechanic.skills.split(',').map(skill=>`<span>${escapeHTML(skill)}</span>`).join('')}</div><div class="mechanic-meta"><span>${escapeHTML(String(mechanic.experience))} years’ experience</span><span>${escapeHTML(mechanic.location)}</span></div><a class="button button-primary mechanic-select" href="emergency.html?mechanic=${encodeURIComponent(mechanic.name)}">Request ${escapeHTML(mechanic.name.split(' ')[0])} <span>↗</span></a></article>`).join('')||'<div class="parts-empty">No mechanics are currently available. Please call 1800 555 0123.</div>';}catch(error){toast(`Mechanic directory could not be refreshed: ${error.message}`);}}
loadMechanics();
window.wrenchApi.request('/api/admin/session').then(session=>{if(session.authenticated)return openAdmin();}).catch(error=>toast(`Admin session could not be checked: ${error.message}`));
